WITH cases AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (140168,36715780,37205056,37205057,4031141,4031142,4031649,4063433,4223485) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1), arthritis AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (81931,40319772,4083682,46274123) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1) SELECT c.concept_id,v.concept_name,v.concept_code,IF(a.concept_id IS NULL,0,1) in_arthritis_set FROM cases c LEFT JOIN arthritis a USING(concept_id) LEFT JOIN `wb-silky-artichoke-2408.C2024Q3R8.concept` v USING(concept_id) ORDER BY concept_id